"""Meaningful speech boundary regressions; no cloud calls or device capture."""
from __future__ import annotations
import array
import base64
import hashlib
import io
import json
import random
from pathlib import Path
import sys
import tempfile
import threading
import time
import types
import unittest
from unittest.mock import patch
import wave
import speech

WORK = Path(__file__).resolve().parent
_FIXTURE_MP3_BASE64 = ''

def wav_data(frames=4097, width=2, rate=16000, *, varying=False):
    stream = io.BytesIO()
    with wave.open(stream, 'wb') as wav:
        wav.setnchannels(1)
        wav.setsampwidth(width)
        wav.setframerate(rate)
        raw = (b'\x23\x01' if width == 2 else b'\x23') * frames
        if varying and width == 2:
            raw = (b'\x23\x01\xdd\xfe' * ((frames + 1) // 2))[:frames * 2]
        wav.writeframes(raw)
    return stream.getvalue()


class FreeRecognitionTests(unittest.TestCase):
    def test_offline_unicode_paths_use_handles_and_ascii_data_arguments(self):
        with tempfile.TemporaryDirectory(prefix='dictation-café-東京-', dir=WORK) as folder:
            path = Path(folder)
            (path / 'whisper-cli.exe').write_bytes(b'fixture')
            (path / speech.OFFLINE_MODEL).write_bytes(b'fixture')
            observed = {}
            class Process:
                returncode = 0
                def poll(self): return 0
                def wait(self, timeout): return 0
            def create(args, **kwargs):
                observed['args'] = args
                self.assertEqual(args[args.index('--model') + 1], speech.OFFLINE_MODEL)
                self.assertEqual(args[args.index('--file') + 1], '-')
                self.assertEqual(args[args.index('--output-file') + 1], 'transcript')
                self.assertNotIn('--output-json', args)
                self.assertEqual(kwargs['cwd'], path)
                self.assertEqual(kwargs['stdin'].read(), wav_data(varying=True))
                kwargs['stdout'].write('Ne payez pas 38,50 euros.\nMerci.\n'.encode('utf-8'))
                return Process()
            with patch.object(speech.subprocess, 'Popen', side_effect=create):
                text = speech.recognize_offline(wav_data(varying=True), 'fr-FR', {'_speech_resources': folder, '_audio_dir': folder}, threading.Event())
            self.assertEqual(text, 'Ne payez pas 38,50 euros. Merci.')
            self.assertTrue(all(value.isascii() for value in observed['args'][1:]))
            self.assertEqual(sorted(p.name for p in path.iterdir()), [speech.OFFLINE_MODEL, 'whisper-cli.exe'])

    def test_offline_empty_invalid_and_oversized_stdout_rejected(self):
        with tempfile.TemporaryDirectory(dir=WORK) as folder:
            path = Path(folder)
            (path / 'whisper-cli.exe').write_bytes(b'fixture')
            (path / speech.OFFLINE_MODEL).write_bytes(b'fixture')
            class Process:
                returncode = 0
                def poll(self): return 0
                def wait(self, timeout): return 0
            for output in (b'', b'\xff\xfe', b'X' * (1024 * 1024 + 1)):
                def create(args, **kwargs):
                    kwargs['stdout'].write(output); return Process()
                with patch.object(speech.subprocess, 'Popen', side_effect=create), self.assertRaises(speech.SpeechError):
                    speech.recognize_offline(wav_data(varying=True), 'en-US', {'_speech_resources': folder, '_audio_dir': folder})
                self.assertEqual(sorted(p.name for p in path.iterdir()), [speech.OFFLINE_MODEL, 'whisper-cli.exe'])

    def test_independent_decoder_bit_perfect_flac_roundtrip(self):
        import miniaudio
        randomizer = random.Random(514)
        for count in (1, 511, 4095, 4096, 4097, 7499, 800000):
            samples = array.array('h', (randomizer.randrange(-32768, 32768) for _ in range(count)))
            raw = samples.tobytes()
            stream = io.BytesIO()
            with wave.open(stream, 'wb') as wav:
                wav.setnchannels(1); wav.setsampwidth(2); wav.setframerate(16000); wav.writeframes(raw)
            encoded = speech.pcm16_to_flac(stream.getvalue())
            decoded = miniaudio.decode(encoded, output_format=miniaudio.SampleFormat.SIGNED16, nchannels=1, sample_rate=16000)
            self.assertEqual(decoded.samples.tobytes(), raw)

    def test_flac_streaminfo_pcm_md5_and_short_final_frame(self):
        for count in (1, 4095, 4096, 4097, 800000):
            audio = wav_data(count)
            encoded = speech.pcm16_to_flac(audio)
            self.assertEqual(encoded[:8], b'fLaC\x80\x00\x00\x22')
            self.assertEqual(int.from_bytes(encoded[18:26], 'big') & ((1 << 36) - 1), count)
            self.assertEqual(encoded[26:42], hashlib.md5(b'\x23\x01' * count).digest())
            self.assertGreater(len(encoded), count * 2)

    def test_format_and_incomplete_recording_rejected(self):
        for value in (b'junk', wav_data(width=1), wav_data(rate=8000), wav_data()[:-2], wav_data(800001)):
            with self.assertRaises(speech.SpeechError):
                speech.pcm16_to_flac(value)

    def test_google_cancel_before_any_network(self):
        stop = threading.Event(); stop.set()
        with patch.object(speech, 'request') as request:
            with self.assertRaises(speech.SpeechError):
                speech.recognize_google_web(wav_data(), 'en-US', stop)
            request.assert_not_called()

    def test_google_final_segments_preserve_negation_and_number(self):
        body = b'{"result":[]}\n{"result":[{"alternative":[{"transcript":"do not pay 38"}],"final":true}]}\n{"result":[{"alternative":[{"transcript":"until Friday"}],"final":true}]}'
        with patch.object(speech, 'request', return_value=body):
            self.assertEqual(speech.recognize_google_web(wav_data(varying=True), 'en-US'), 'do not pay 38 until Friday')

    def test_google_invalid_or_no_speech_never_success(self):
        for body in (b'not json', b'{"result":[]}', b'{"result":[{"alternative":[{"transcript":null}]}]}'):
            with patch.object(speech, 'request', return_value=body), self.assertRaises(speech.SpeechError):
                speech.recognize_google_web(wav_data(varying=True), 'en-US')

    def test_auto_failure_runs_offline_and_labels_it(self):
        with patch.object(speech, 'recognize_google_web', side_effect=speech.SpeechError('Unavailable')), patch.object(speech, 'recognize_offline', return_value='do not pay 38') as offline:
            value = speech.recognize_with_fallback(wav_data(varying=True), 'ar-SA', {'speech_provider': 'auto'})
            self.assertEqual(value['provider'], 'offline')
            self.assertEqual(value['text'], 'do not pay 38')
            self.assertTrue(value['warnings'])
            offline.assert_called_once()

    def test_cancel_during_google_never_sends_to_fallback(self):
        stop = threading.Event()
        def cancelled(*args):
            stop.set(); raise speech.SpeechError('Cancelled')
        with patch.object(speech, 'recognize_google_web', side_effect=cancelled), patch.object(speech, 'recognize_offline') as offline, self.assertRaises(speech.SpeechError):
            speech.recognize_with_fallback(wav_data(varying=True), 'ar-SA', {'speech_provider': 'auto'}, stop)
        offline.assert_not_called()

    def test_unverified_languages_are_not_substituted(self):
        for language in ('fa-AF', 'ti-ET', 'om-ET', 'ckb-IQ', 'ku-TR'):
            self.assertFalse(speech.recognition_supported(language, 'offline'))
            with patch.object(speech.subprocess, 'Popen') as process, self.assertRaises(speech.SpeechError):
                speech.recognize_offline(wav_data(), language)
